-- Canonical fact view: every company's figures under one metric vocabulary.
CREATE SCHEMASTORE VIEW financial_fact WITH CONTAINER edgar AS
SELECT
    'TGT' AS ticker,
    'revenue' AS metric,
    LPAD(CAST(cik AS STRING), 10, '0') AS cik,
    `entityName` AS entity_name,
    tag AS xbrl_tag,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    CAST(fact.val AS DOUBLE) AS value_usd,
    fact.accn AS accession_number,
    fact.fy AS fiscal_year,
    fact.fp AS fiscal_period,
    fact.form AS form_type,
    fact.filed AS filed_date,
    fact.frame AS period_frame
FROM sec_data.tgt_revenue_raw
LATERAL VIEW explode(units.USD) AS fact
UNION ALL
SELECT
    'TGT' AS ticker,
    'cost_of_sales' AS metric,
    LPAD(CAST(cik AS STRING), 10, '0') AS cik,
    `entityName` AS entity_name,
    tag AS xbrl_tag,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    CAST(fact.val AS DOUBLE) AS value_usd,
    fact.accn AS accession_number,
    fact.fy AS fiscal_year,
    fact.fp AS fiscal_period,
    fact.form AS form_type,
    fact.filed AS filed_date,
    fact.frame AS period_frame
FROM sec_data.tgt_cost_of_sales_raw
LATERAL VIEW explode(units.USD) AS fact
UNION ALL
SELECT
    'TGT' AS ticker,
